urlset:
{% if 'home' not in hidden_pages %}
  {{ request.scheme }}://{{ request.get_host }}/
  weekly
  1.0
{% endif %}
{% if 'portfolio_index' not in hidden_pages %}
  {{ request.scheme }}://{{ request.get_host }}{% url 'portfolio:project_list' %}
  weekly
  0.8
{% endif %}
{% if 'contact' not in hidden_pages %}
  {{ request.scheme }}://{{ request.get_host }}{% url 'leads:contact' %}
  monthly
  0.8
{% endif %}
{% if 'blog_index' not in hidden_pages %}{{ request.scheme }}://{{ request.get_host }}{% url 'blog:blog_list' %}{% endif %}
{% if 'tools' not in hidden_pages %}{{ request.scheme }}://{{ request.get_host }}{% url 'tools:index' %}{% endif %}
{% for post in blog_posts %}
{{ request.scheme }}://{{ request.get_host }}{{ post.get_absolute_url }}{{ post.datetime_updated|date:"Y-m-d" }}
{% endfor %}
{% for project in portfolio_projects %}

  {{ request.scheme }}://{{ request.get_host }}{{ project.get_absolute_url }}
  {{ project.updated_at|date:"Y-m-d" }}
  monthly
  0.7

{% endfor %}
